const http = require("http");
const fs = require("fs");
const path = require("path");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = fs.mkdtempSync("/tmp/wr-");
fs.writeFileSync(path.join(dir, "index.js"), "export default { fetch() { return new Response('ok'); } };\n");
fs.writeFileSync(path.join(dir, "wrangler.json"), JSON.stringify({ name: "test-worker", main: "index.js", compatibility_date: "2025-01-01", workers_dev: true, routes: [{ pattern: "api.example.com", custom_domain: true, previews_enabled: true }] }));
const W = "/accounts/acc123/workers/scripts/test-worker";
const seen = [];
const server = http.createServer((req, res) => {
  let body = "";
  req.on("data", (c) => { body += c; });
  req.on("end", () => {
    const u = req.url.split("?")[0].replace(/^\/client\/v4/, "");
    seen.push(req.method + " " + u);
    let result = {};
    if (u === "/accounts/acc123/workers/subdomain") result = { subdomain: "example" };
    else if (u === W + "/subdomain") result = { enabled: true, previews_enabled: false };
    else if (u === W + "/domains/changeset") {
      let origins = [];
      try { origins = JSON.parse(body || "[]"); } catch (e) {}
      result = { added: origins.map((o, i) => ({ id: String(101 + i), zone_id: "", zone_name: "", hostname: o.hostname, service: "test-worker", environment: "", enabled: true, previews_enabled: o.previews_enabled === true })), removed: [], updated: [], conflicting: [] };
    } else if (u === W + "/domains/records") result = null;
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ success: true, errors: [], messages: [], result }));
  });
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const env = Object.assign({}, process.env, { HOME: "/tmp", CI: "1", NO_COLOR: "1", FORCE_COLOR: "0", CLOUDFLARE_API_TOKEN: "test-token", CLOUDFLARE_ACCOUNT_ID: "acc123", CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4", WRANGLER_SEND_METRICS: "false", WRANGLER_NO_SKILLS_UPDATE_PROMPTS: "true" });
  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "triggers", "deploy"], { cwd: dir, env, stdio: ["ignore", "pipe", "pipe"] });
  let out = "";
  child.stdout.on("data", (d) => { out += d; });
  child.stderr.on("data", (d) => { out += d; });
  const timer = setTimeout(() => { child.kill("SIGKILL"); broken("wrangler triggers deploy timed out: " + out.slice(-1500)); }, 80000);
  child.on("exit", (code) => {
    clearTimeout(timer);
    server.close();
    if (code !== 0) broken("wrangler triggers deploy exited " + code + ": " + out.slice(-1500) + " requests: " + seen.join(", "));
    if (!seen.includes("PUT " + W + "/domains/records")) broken("the custom domain was not published; requests: " + seen.join(", "));
    if (!out.includes("api.example.com (custom domain)")) broken("the deploy output does not list the custom domain: " + out.slice(-1500));
    if (!out.includes("DNS and TLS certificate provisioning")) symptom("deploy that adds a Preview-enabled custom domain prints no DNS and TLS provisioning note");
    console.log("OK: deploy prints the DNS and TLS certificate provisioning note");
    process.exit(0);
  });
});

